const storage = $('Code - prepare storage & decrypt2').first().json;
const item = $input.first();

if (!item.binary?.data) {
  return [{ json: { skipped: true, reason: 'No audio binary — download may have failed or message is not audio' } }];
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');

const mime = (storage.mime_type ?? '').toLowerCase();
const formatMap = [
  ['ogg', 'ogg'],
  ['opus', 'ogg'],
  ['mpeg', 'mp3'],
  ['mp3', 'mp3'],
  ['m4a', 'm4a'],
  ['mp4', 'm4a'],
  ['wav', 'wav'],
  ['webm', 'webm'],
  ['aac', 'aac'],
  ['flac', 'flac'],
];

let format = 'ogg';
for (const [needle, fmt] of formatMap) {
  if (mime.includes(needle)) {
    format = fmt;
    break;
  }
}

return [{
  json: {
    message_id: storage.message_id,
    owner_email: storage.owner_email,
    owner_phone_num: storage.owner_phone_num,
    media_kind: storage.media_kind,
    chirp_body: {
       model: 'google/chirp-3',
       // model:'microsoft/mai-transcribe-1.5',
       // "language": "my-MM",
  // "language": "my",
    "temperature": 0.2,
         // "model": "openai/whisper-large-v3-turbo",  
      // "model": "openai/whisper-large-v3",
      input_audio: {
        data: base64,
        format,
      },
    },
  },
}];

const prep = $('Code - prepare Chirp 3 base65').first().json;
const res = $input.first().json;

const text =
  res.text ??
  res.transcript ??
  res.data?.text ??
  res.choices?.[0]?.message?.content ??
  '';

if (!text) {
  return [{ json: { skipped: true, reason: 'Chirp 3 returned no text', raw: res } }];
}

return [{
  json: {
    message_id: prep.message_id,
    owner_email: prep.owner_email,
    owner_phone_num: prep.owner_phone_num,
    transcript: String(text).trim(),
    model_name: 'google/chirp-3',
  },
}];

