INSERT INTO actionnow.whatsapp_media_interpretations (
  media_id, message_id, owner_email, owner_phone_num,
  interpretation_type, status
) VALUES (
  $1::uuid, $2, $3, $4, $5, 'pending'
)
ON CONFLICT (media_id, interpretation_type) DO NOTHING
RETURNING id, interpretation_type;

