const storage = $('Code - prepare storage & decrypt2').first().json;
const parsed = $('Code - parse message & media type3').first().json;
const monitor = parsed.monitor_settings ?? $('Postgres - get monitor settings for owner3').first()?.json ?? {};
const item = $input.first();

if (!item.binary?.data) {
  return [{ json: { skipped: true, reason: 'No image binary on item — check HTTP download outputPropertyName=data' } }];
}

const keywords = (monitor.what_content_keywords ?? []).filter(Boolean).join(', ') || 'none specified';
const monitorName = monitor.monitor_name ?? 'monitoring';
const contentTypes = (monitor.what_content_types ?? []).filter(Boolean).join(', ') || 'all';
const caption = parsed.message_body ?? '';

const llm_prompt = `You are an expert alert manager for "${monitorName}" (owner: ${storage.owner_email}).\nWatch for keywords: ${keywords}.\nContent types of interest: ${contentTypes}.\nWhatsApp caption/context: ${caption || 'n/a'}\n\nAnalyze this WhatsApp image. Be vividly specific about what you see. Return plain text with sections:\nSCENE: what is shown\nTEXT: all visible text (OCR)\nALERTS: issues, hazards, complaints, or items matching the keywords above\nKeep it verbose but focused on the monitoring context.`;

return [{
  json: {
    message_id: storage.message_id,
    owner_email: storage.owner_email,
    owner_phone_num: storage.owner_phone_num,
    model_name: 'google/gemini-2.5-flash-preview',
    llm_prompt,
  },
  binary: item.binary,
}];

const prep = $('Code - pass image binary to LLM2').first().json;
const res = $input.first().json;

const text = res.text ?? res.response ?? res.output ?? '';

if (!text) {
  return [{ json: { skipped: true, reason: 'LLM Chain returned no text', raw: res } }];
}

return [{
  json: {
    message_id: prep.message_id,
    content: String(text).trim(),
    model_name: prep.model_name,
  },
}];

const storage = $('Code - prepare storage & decrypt2').first().json;
const parsed = $('Code - parse message & media type3').first().json;
const item = $input.first();

if (!item.binary?.data) {
  return [{ json: { skipped: true, reason: 'No document binary — check HTTP download outputPropertyName=data' } }];
}

const mime = (storage.mime_type ?? 'application/octet-stream').toLowerCase();
const fileName = parsed.media_row?.file_name ?? 'document.bin';
const model_name = 'google/gemini-2.5-flash-preview';

const base = {
  message_id: storage.message_id,
  owner_email: storage.owner_email,
  owner_phone_num: storage.owner_phone_num,
  file_name: fileName,
  mime_type: mime,
  model_name,
};

const isPlainText =
  mime.startsWith('text/') ||
  mime === 'application/json' ||
  /\.(txt|csv|md|json|log)$/i.test(fileName);

if (isPlainText) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  const plain_text = buffer.toString('utf8').trim();
  if (!plain_text) {
    return [{ json: { ...base, skipped: true, reason: 'Text file is empty' } }];
  }
  return [{ json: { ...base, plain_text, needs_extract: false, source: 'utf8' } }];
}

return [{
  json: { ...base, needs_extract: true, source: 'binary' },
  binary: item.binary,
}];

const reader = $('Code - read document text2').first().json;
const parsed = $('Code - parse message & media type3').first().json;
const monitor = parsed.monitor_settings ?? $('Postgres - get monitor settings for owner3').first()?.json ?? {};
const item = $input.first().json;

let plain_text = reader.plain_text ?? '';

if (reader.needs_extract) {
  plain_text = String(item.text ?? item.data ?? '').trim();
}

if (!plain_text) {
  return [{
    json: {
      skipped: true,
      reason: 'No text extracted — PDF may be scanned/image-only; try OpenRouter file fallback or OCR',
      message_id: reader.message_id,
      file_name: reader.file_name,
    },
  }];
}

const keywords = (monitor.what_content_keywords ?? []).filter(Boolean).join(', ') || 'none specified';
const monitorName = monitor.monitor_name ?? 'monitoring';
const contentTypes = (monitor.what_content_types ?? []).filter(Boolean).join(', ') || 'all';
const caption = parsed.message_body ?? '';

const llm_prompt = `Analyze this WhatsApp document for business monitoring ("${monitorName}", owner: ${reader.owner_email}).\nWatch for keywords: ${keywords}.\nContent types of interest: ${contentTypes}.\nWhatsApp caption/context: ${caption || 'n/a'}\n\nReturn plain text with sections:\nSUMMARY: main points\nKEY TEXT: important names, dates, amounts, references\nALERTS: issues, deadlines, complaints, or items matching the keywords above\n\n--- DOCUMENT ---\n${plain_text}`;

return [{
  json: {
    message_id: reader.message_id,
    owner_email: reader.owner_email,
    owner_phone_num: reader.owner_phone_num,
    plain_text,
    model_name: reader.model_name,
    source: reader.source,
    llm_prompt,
  },
}];

const prep = $('Code - pass document text to LLM2').first().json;
const res = $input.first().json;

const text = res.text ?? res.response ?? res.output ?? '';

if (!text) {
  return [{ json: { skipped: true, reason: 'LLM Chain returned no text', raw: res } }];
}

return [{
  json: {
    message_id: prep.message_id,
    content: String(text).trim(),
    model_name: prep.model_name,
  },
}];
